//! Explicit V3 initial-baseline byte authentication, not installed authority.
//! Shares the sole manifest parser/signature verifier and full-content decoder.
use std::io::{Read, Seek, Write};
use ed25519_dalek::VerifyingKey;
use keld_guard::windows_qualification_catalog::DeploymentQualifiedWindowsCatalog;
