#[derive(Debug)]
pub(crate) struct VersionedBaselineVerifier {
    record: Record,
    release_key: VerifyingKey,
}
impl VersionedBaselineVerifier {
    pub(crate) fn new(
        record: Record, catalog: &DeploymentQualifiedWindowsCatalog, public_key: &[u8; 32],
    ) -> Result<Self, UpdateError> {
        require_catalog_binding(&record, catalog)?;
        let release_key = VerifyingKey::from_bytes(public_key).map_err(|e| invalid(e.to_string()))?;
        if release_key.is_weak() || record.signing_key_id != SigningKeyId::from_public_key(public_key) {
            return Err(invalid("release key differs or is weak"));
        }
        Ok(Self { record, release_key })
    }
    pub(crate) fn verify_manifest(&self, bytes: &[u8], signature: &[u8]) -> Result<SelectedVersionedBaseline, UpdateError> {
        let scope = ManifestScope { app_id: &self.record.app_id, channel: self.record.channel, target: &self.record.target };
        let releases = authenticate_manifest_scope(scope, &self.release_key, bytes, signature)?;
        let artifact = select_baseline_scope(scope, &self.record.baseline, releases)?;
        Ok(SelectedVersionedBaseline { record: self.record.clone(), artifact })
    }
}

#[derive(Debug)]
pub(crate) struct SelectedVersionedBaseline {
    record: Record,
    artifact: SignedFullArtifact,
}
impl SelectedVersionedBaseline {
    pub(crate) fn verify_full<R: Read + Seek, W: Write>(&self, source: &mut R, sink: &mut W) -> Result<VerifiedVersionedBaseline, UpdateError> {
        Ok(VerifiedVersionedBaseline { record: self.record.clone(), content: self.artifact.verify_content(source, sink)? })
    }
}
#[derive(Debug)]
pub(crate) struct VerifiedVersionedBaseline {
    record: Record,
    content: crate::full::ContentIdentity,
}
impl VerifiedVersionedBaseline {
    pub(crate) fn record(&self) -> &Record { &self.record }
    pub(crate) fn identity(&self) -> &ArtifactIdentity { &self.content.identity }
    pub(crate) fn content_size(&self) -> u64 { self.content.content_size }
    pub(crate) fn validate_archive<R: Read + Seek>(&self, source: &mut R) -> Result<crate::ValidatedArchive, UpdateError> {
        crate::archive::parse_content_archive(&self.content, source, keld_guard::validate_windows_package_paths)
    }
}

/// Matches logical configuration to opaque deployment assertions. This does NOT
/// promote the record to protected installation authority; that requires OS loading.
pub(crate) fn require_catalog_binding(record: &Record, catalog: &DeploymentQualifiedWindowsCatalog) -> Result<(), UpdateError> {
    crate::records::profile_binding_v3::encode_windows_versioned_installation(record)?;
    if record.install_mode != crate::DirectInstallMode::PerUserDirect || record.target != "windows-x64" {
        return Err(invalid("V3 initial baseline supports only PerUserDirect windows-x64"));
    }
    let expected=crate::ExpectedAppIdentity::from_signed_image(catalog.host().file())?;
    require_expected_record(&expected,record)?;
    let host = catalog.host().identity();
    if &record.publisher_scope != host.publisher_scope() || record.app_id != host.app_id() {
        return Err(invalid("V3 publisher or application differs from retained Host"));
    }
    let authenticated = catalog.catalog();
    let identity = authenticated.identity();
    let (catalog_digest,authority_digest)=catalog_binding_digests(authenticated.signed_bytes(),authenticated.authority_public_key());
    require_template_fields(&record.profile_binding, identity, catalog_digest, authority_digest)
}
pub(crate) fn require_expected_record(expected:&crate::ExpectedAppIdentity,record:&Record) -> Result<(),UpdateError> {
    if expected.app_id!=record.app_id || expected.channel!=record.channel || expected.target!=record.target
        || expected.signing_key_id!=record.signing_key_id {
        return Err(invalid("signed Host embedded expectation differs from V3 record"));
    }
    Ok(())
}

fn catalog_binding_digests(bytes:&[u8], key:&[u8;32]) -> ([u8;32],[u8;32]) {
    let catalog_digest: [u8;32] = Sha256::digest(bytes).into();
    let mut authority=Sha256::new();
    authority.update(b"keld.windows.qualification-authority/v1\0");authority.update(key);
    (catalog_digest,authority.finalize().into())
}

fn require_template_fields(binding: &Binding, identity: &keld_guard::windows_qualification_catalog::WindowsQualificationIdentity,
    observed_catalog: [u8;32], observed_authority: [u8;32]) -> Result<(), UpdateError> {
    match binding {
        Binding::WindowsQualifiedTemplateV1 { template_digest, catalog_digest, qualification_authority_digest,
            creator_digest, os_policy_digest, policy_generation }
            if *template_digest == identity.template_digest && *catalog_digest == observed_catalog
                && *qualification_authority_digest == observed_authority && *creator_digest == identity.creator_digest
                && *os_policy_digest == identity.os_policy_digest && *policy_generation == identity.policy_generation => Ok(()),
        _ => Err(invalid("V3 qualified template tuple differs; exact-profile is not a template")),
    }
}
fn invalid(detail: impl Into<String>) -> UpdateError { UpdateError::Baseline { step: "versioned initial baseline", detail: detail.into() } }

