                qualification_authority_digest:[3;32],creator_digest:[4;32],os_policy_digest:[5;32],policy_generation:2 },
            publisher_scope:[6;32],volume_guid:"fixture".into() };
        require_expected_record(&expected,&record).expect("matching embedded expectation");
        for field in 0..4 {
            let mut changed=record.clone();
            match field { 0=>changed.app_id.push('x'),1=>changed.channel=crate::Channel::Beta,
                2=>changed.target="windows-arm64".into(),_=>changed.signing_key_id=crate::SigningKeyId::from_public_key(&[8;32]) }
            assert!(require_expected_record(&expected,&changed).is_err());
        }
    }
    #[test]
    fn template_every_field_and_variant_are_exact() {
        let identity = keld_guard::windows_qualification_catalog::WindowsQualificationIdentity {
            artifact_digest:[9;32], template_digest:[1;32], creator_digest:[4;32], os_policy_digest:[5;32], policy_generation:2 };
        let value = Binding::WindowsQualifiedTemplateV1 { template_digest:[1;32], catalog_digest:[2;32],
            qualification_authority_digest:[3;32], creator_digest:[4;32], os_policy_digest:[5;32], policy_generation:2 };
        require_template_fields(&value,&identity,[2;32],[3;32]).expect("exact tuple");
        for field in 0..6 {
            let mut changed=value.clone();
            if let Binding::WindowsQualifiedTemplateV1 { template_digest,catalog_digest,qualification_authority_digest,
                creator_digest,os_policy_digest,policy_generation }=&mut changed {
                match field { 0=>template_digest[0]^=1,1=>catalog_digest[0]^=1,2=>qualification_authority_digest[0]^=1,
                    3=>creator_digest[0]^=1,4=>os_policy_digest[0]^=1,_=>*policy_generation+=1 }
            }
            assert!(require_template_fields(&changed,&identity,[2;32],[3;32]).is_err());
        }
        assert!(require_template_fields(&Binding::ExactProfileV1(keld_guard::ProfileDigest([1;32])),&identity,[2;32],[3;32]).is_err());
    }
}

/// Before publication, require the closed readable members and bind actual archived
/// Host/runtime bytes to the deployment-qualified creator and runtime. No launch.
pub(crate) fn require_archive_qualified_members(
    archive: &crate::ValidatedArchive, source: &cap_std::fs::File,
    catalog: &DeploymentQualifiedWindowsCatalog,
) -> Result<(),UpdateError> {
    let recipe=catalog.primary_read_recipe();
    require_readable_members(archive.entries().iter().filter(|entry|entry.kind()==crate::ArchiveEntryKind::File)
        .map(|entry|entry.name()),recipe.read_execute_members())?;
    let pin=source.try_clone().map_err(|e|invalid(e.to_string()))?.into_std();
    for (name,expected) in [("keld-host.exe",catalog.catalog().identity().creator_digest),
        (recipe.runtime_member(),recipe.runtime_artifact_digest().0)] {
        let entry=archive.entries().iter().find(|entry|entry.name()==name && entry.kind()==crate::ArchiveEntryKind::File)
            .ok_or_else(||invalid("qualified executable member missing"))?;
        require_member_digest(&pin,entry.data_offset(),entry.size(),archive.content_size(),expected)?;
    }
    Ok(())
}

fn require_readable_members<'a>(available:impl Iterator<Item=&'a str>,required:&[&str]) -> Result<(),UpdateError> {
    let available:std::collections::BTreeSet<_>=available.collect();
    if required.iter().any(|name|!available.contains(name)) {
        return Err(invalid("required closed-recipe member missing from initial archive"));
    }
    Ok(())
}

pub(crate) fn require_member_digest(source:&std::fs::File, start:u64, size:u64, archive_size:u64, expected:[u8;32]) -> Result<(),UpdateError> {
    use std::os::windows::fs::FileExt as _;
    if size==0 || size>512*1024*1024 { return Err(invalid("qualified Host size unsupported")); }
    let end=start.checked_add(size).ok_or_else(||invalid("Host extent overflow"))?;
    if end>archive_size || source.metadata().map_err(|e|invalid(e.to_string()))?.len()!=archive_size {
        return Err(invalid("Host extent or archive size differs from authenticated inventory"));
    }
    let mut digest=Sha256::new(); let mut offset=start; let mut buffer=[0_u8;16*1024];
    while offset<end {
        let wanted=usize::try_from((end-offset).min(buffer.len() as u64)).map_err(|e|invalid(e.to_string()))?;
        let count=source.seek_read(&mut buffer[..wanted],offset).map_err(|e|invalid(e.to_string()))?;
        if count==0 { return Err(invalid("Host member truncated")); }
        digest.update(&buffer[..count]); offset+=u64::try_from(count).map_err(|e|invalid(e.to_string()))?;
    }
    let actual:[u8;32]=digest.finalize().into();
    if actual!=expected { return Err(invalid("archived Host differs from qualified signed creator")); }
    Ok(())
}

