    #[test]
    fn missing_runtime_main_or_transport_refuses_before_publication() {
        let required=["bun.exe","code/main.js","code/kipc-transport.js"];
        require_readable_members(required.into_iter(),&required).expect("complete closed members");
        for missing in 0..required.len() {
            assert!(require_readable_members(required.iter().enumerate().filter(|(index,_)|*index!=missing)
                .map(|(_,name)|*name),&required).is_err());
        }
    }
    #[test]
    fn actual_member_offsets_full_buffers_digest_and_truncation_are_bound() {
        let mut source=tempfile::tempfile().expect("fixture");
        let bytes:Vec<u8>=(0..32799).map(|i|u8::try_from(i%251).expect("byte")).collect();
        source.write_all(b"head!").unwrap(); source.write_all(&bytes).unwrap();source.write_all(b"tail").unwrap();
        let length=32808;
        // Independent Python hashlib.sha256 of index%251 for 32,799 bytes.
        let digest=[0xd8,0x83,0xaa,0xeb,0xdf,0x1d,0x70,0x29,0xb5,0x2a,0x52,0x6e,0x9d,0xd4,0x18,0x70,
            0x63,0x0a,0x0f,0xb7,0xa6,0x58,0xbe,0xd6,0xbf,0x96,0x9d,0x4b,0x2d,0x62,0xce,0x05];
        source.seek(SeekFrom::End(0)).unwrap();
        require_member_digest(&source,5,32799,length,digest).expect("offset hashing ignores shared cursor");
        assert!(require_member_digest(&source,4,32799,length,digest).is_err());
        assert!(require_member_digest(&source,5,32798,length,digest).is_err());
        assert!(require_member_digest(&source,5,32799,length,[0;32]).is_err());
        assert!(require_member_digest(&source,u64::MAX,1,length,digest).is_err());
        assert!(require_member_digest(&source,5,0,length,digest).is_err());
        assert!(require_member_digest(&source,5,512*1024*1024+1,length,digest).is_err());
        source.seek(SeekFrom::Start(5+16384)).unwrap();source.write_all(&[255]).unwrap();
        assert!(require_member_digest(&source,5,32799,length,digest).is_err());
        source.set_len(20).unwrap();
        assert!(require_member_digest(&source,5,32799,length,digest).is_err());
    }
}

