#[derive(Serialize, Deserialize)]
#[serde(tag = "kind", deny_unknown_fields)]
enum WireBinding {
    #[serde(rename = "exact-profile/v1")]
    ExactProfileV1 { profile_digest: String },
    #[serde(rename = "windows-qualified-template/v1")]
    WindowsQualifiedTemplateV1 {
        template_digest: String,
        catalog_digest: String,
        qualification_authority_digest: String,
        creator_digest: String,
        os_policy_digest: String,
        policy_generation: u64,
    },
}
#[derive(Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct Wire {
    schema: String,
    owner: String,
    protection_profile: String,
    install_mode: String,
    app_id: String,
    channel: String,
    target: String,
    install_root: String,
    update_root: String,
    signing_key_id: String,
    baseline: WireArtifact,
    profile_binding: WireBinding,
    principal_model: String,
    publisher_scope: String,
    volume_guid: String,
}
fn binding_to_wire(binding: &Binding) -> Result<WireBinding, UpdateError> {
    Ok(match binding {
        Binding::ExactProfileV1(value) => WireBinding::ExactProfileV1 { profile_digest: hex_digest(&value.0) },
        Binding::WindowsQualifiedTemplateV1 { template_digest, catalog_digest, qualification_authority_digest,
            creator_digest, os_policy_digest, policy_generation } => {
            if [template_digest, catalog_digest, qualification_authority_digest, creator_digest, os_policy_digest]
                .iter().any(|value| **value == [0; 32]) || *policy_generation < keld_guard::policy_generation_for(keld_guard::HostOs::Windows) {
                return Err(invalid("template binding has empty identity or stale Windows policy"));
            }
            WireBinding::WindowsQualifiedTemplateV1 {
                template_digest: hex_digest(template_digest), catalog_digest: hex_digest(catalog_digest),
                qualification_authority_digest: hex_digest(qualification_authority_digest),
                creator_digest: hex_digest(creator_digest), os_policy_digest: hex_digest(os_policy_digest),
                policy_generation: *policy_generation,
            }
        }
    })
}
fn binding_from_wire(wire: WireBinding) -> Result<Binding, UpdateError> {
    let value = match wire {
        WireBinding::ExactProfileV1 { profile_digest } => Binding::ExactProfileV1(keld_guard::ProfileDigest(digest(&profile_digest)?)),
        WireBinding::WindowsQualifiedTemplateV1 { template_digest, catalog_digest, qualification_authority_digest,
            creator_digest, os_policy_digest, policy_generation } => Binding::WindowsQualifiedTemplateV1 {
            template_digest: digest(&template_digest)?, catalog_digest: digest(&catalog_digest)?,
            qualification_authority_digest: digest(&qualification_authority_digest)?,
            creator_digest: digest(&creator_digest)?, os_policy_digest: digest(&os_policy_digest)?, policy_generation,
        },
    };
    binding_to_wire(&value)?;
    Ok(value)
}
/// Encodes canonical v3 logical provenance, without creating trust or publishing it.
/// # Errors
/// Refuses inconsistent artifact identity, invalid roots, stale template policy or oversized bytes.
pub fn encode_windows_versioned_installation(record: &Record) -> Result<Vec<u8>, UpdateError> {
    if record.app_id.is_empty() || record.app_id != record.baseline.app_id
        || record.channel != record.baseline.channel || record.target != record.baseline.target
        || !matches!(record.target.as_str(), "windows-x64" | "windows-arm64") {
        return Err(invalid("inconsistent Windows installation artifact identity"));
    }
    nonempty(&record.volume_guid)?;
    encode(&Wire {
        schema: SCHEMA.to_owned(), owner: "direct".to_owned(),
        protection_profile: record.install_mode.protection_profile().as_str().to_owned(),
        install_mode: record.install_mode.as_str().to_owned(), app_id: record.app_id.clone(),
        channel: record.channel.as_str().to_owned(), target: record.target.clone(),
        install_root: path_text(&record.install_root)?.to_owned(), update_root: path_text(&record.update_root)?.to_owned(),
        signing_key_id: hex_digest(record.signing_key_id.as_bytes()), baseline: wire_artifact(&record.baseline)?,
        profile_binding: binding_to_wire(&record.profile_binding)?, principal_model: "strict-distinct-os-principals".to_owned(),
        publisher_scope: hex_digest(&record.publisher_scope), volume_guid: record.volume_guid.clone(),
    })
}
/// Decodes only canonical v3 logical provenance. Never returns protected provenance or a permit.
/// # Errors
/// Refuses old/unknown schemas, unknown/duplicate fields, malformed tags and inconsistent identities.
pub fn decode_windows_versioned_installation(bytes: &[u8]) -> Result<Record, UpdateError> {
    let wire: Wire = decode(bytes)?;
    schema(&wire.schema, SCHEMA)?;
    let install_mode = crate::DirectInstallMode::parse(&wire.install_mode)?;
    if wire.owner != "direct" || wire.principal_model != "strict-distinct-os-principals"
        || wire.protection_profile != install_mode.protection_profile().as_str() {
        return Err(invalid("unsupported v3 owner, principal model or protection profile"));
    }
    let record = Record {
        install_mode, app_id: wire.app_id, channel: channel(&wire.channel)?, target: wire.target,
        install_root: wire.install_root.into(), update_root: wire.update_root.into(),
        signing_key_id: SigningKeyId::from_digest(digest(&wire.signing_key_id)?), baseline: artifact(wire.baseline)?,
        profile_binding: binding_from_wire(wire.profile_binding)?, publisher_scope: digest(&wire.publisher_scope)?,
        volume_guid: wire.volume_guid,
    };
    encode_windows_versioned_installation(&record)?;
    Ok(record)
}

