/// The complete canonical archive validated against the selected protected record.
/// Keeps the source file and selected ancestry alive; never authorizes writes there.
#[derive(Debug)]
pub(crate) struct SelectedGenerationSource {
    selection: SelectedGenerationIdentity,
    source: File,
    archive: ValidatedArchive,
}
impl SelectedGenerationSource {
    /// Transfers all source custody together to the private staging owner.
    /// The recipient must retain selection through its stage lifetime.
    pub(crate) fn into_stage_source(self) -> (SelectedGenerationIdentity, File, ValidatedArchive) {
        (self.selection, self.source, self.archive)
    }
}
impl ActivePackageSelection {
    /// Revalidates the retained canonical content using the existing archive owner.
    /// Identity and size come exclusively from protected completion/selection.
    /// No ambient path, caller hash/list, release key or generic verifier callback.
    pub(crate) fn open_generation_source(self: &Arc<Self>) -> Result<SelectedGenerationSource, UpdateError> {
        let (source, archive) = super::load::read_selected_archive(&self._roots, &self.artifact)?;
        Ok(SelectedGenerationSource { selection: SelectedGenerationIdentity::Exact(Arc::clone(self)), source, archive })
    }
}

/// Closed protected selection variants; never a logical record constructor.
