//! Fresh per-user generation workspace derived solely from a selected source owner.
//! This is temporary object custody, not authenticated generation admission.
use std::path::{Path, PathBuf};
use cap_fs_ext::MetadataExt as _;
use cap_std::fs::{Dir, File};
use super::SelectedGenerationSource;
use crate::{DirectInstallMode, UpdateError, ValidatedArchive};
use super::SelectedGenerationIdentity;

/// Consumed selected source plus any freshly created workspace, including failure.
#[derive(Debug)]
pub(crate) struct PreparedGenerationInputs {
    source: SelectedGenerationSource,
    ready: bool,
    parent: Option<Dir>,
    root: Option<Dir>,
    leaf: String,
    path: PathBuf,
}
/// No automatic rollback: any created workspace and source remain discoverable.
#[derive(Debug)]
pub(crate) struct GenerationWorkspaceFailure {
    pub(crate) detail: String,
    pub(crate) inputs: PreparedGenerationInputs,
}
/// Retained source ancestry and exact fresh workspace through generation retirement.
#[derive(Debug)]
pub(crate) struct GenerationWorkspaceLease {
    selection: SelectedGenerationIdentity,
    _parent: Dir,
    root: Dir,
    leaf: String,
    path: PathBuf,
}
impl SelectedGenerationSource {
    /// Creates only a new owner-private sibling of the selected per-user install.
    /// Existing installed objects are never granted access or modified.
    pub(crate) fn prepare_workspace(self) -> Result<PreparedGenerationInputs, GenerationWorkspaceFailure> {
        let mut inputs = PreparedGenerationInputs {
            source: self, ready: false, parent: None, root: None, leaf: String::new(), path: PathBuf::new(),
        };
        if let Err(error) = inputs.create() {
            return Err(GenerationWorkspaceFailure { detail: error.to_string(), inputs });
        }
        Ok(inputs)
    }
}
impl PreparedGenerationInputs {
    fn create(&mut self) -> Result<(), UpdateError> {
        let selection = &self.source.selection;
        if selection.install_mode() != DirectInstallMode::PerUserDirect {
            return Err(super::super::error("generation workspace", "only selected per-user installation is admitted"));
        }
        let index = selection.ancestors().len().checked_sub(2)
            .ok_or_else(|| super::super::error("generation workspace", "retained install parent absent"))?;
        let parent = selection.ancestors()[index].try_clone()
            .map_err(|error| super::super::error("generation parent clone", error))?;
        let path = selection.install_root().parent()
            .ok_or_else(|| super::super::error("generation workspace", "install parent path absent"))?;
        self.leaf = super::super::random_leaf_name("keld-generation-v1")
            .map_err(|error| super::super::error("generation workspace name", error))?;
        self.path = path.join(&self.leaf);
        let parent_file = parent.try_clone().map_err(|error| super::super::error("generation parent handle", error))?.into_std_file();
        self.parent = Some(parent);
        let root = crate::windows_fs::create_directory_relative(&parent_file, &self.leaf)
            .map_err(|error| super::super::error("generation workspace create", error))?;
        // Infallible custody attachment immediately after successful creation.
        self.root = Some(Dir::from_std_file(root));
        let root = self.root.as_ref().ok_or_else(|| super::super::error("generation workspace", "created root absent"))?;
        let root_file = root.try_clone().map_err(|error| super::super::error("generation root clone", error))?.into_std_file();
        keld_guard::validate_windows_owner_private_directory(&root_file)
            .map_err(|error| super::super::error("generation root protection", error))?;
        let volume = selection.ancestors()[index].dir_metadata()
            .map_err(|error| super::super::error("generation parent identity", error))?.dev();
        if root.dir_metadata().map_err(|error| super::super::error("generation root identity", error))?.dev() != volume {
            return Err(super::super::error("generation workspace", "fresh root crossed retained volume"));
        }
        self.ready = true;
        Ok(())
    }
    /// Transfers only successfully created inputs to the existing private stage.
    /// No caller-selected parent, source pair or leaf is accepted.
    pub(crate) fn into_stage_parts(mut self) -> Result<(GenerationWorkspaceLease, File, ValidatedArchive), Self> {
        if !self.ready { return Err(self); }
        let Some(parent) = self.parent.take() else { return Err(self); };
        let Some(root) = self.root.take() else {
            self.parent = Some(parent);
            return Err(self);
        };
        let Self { source, leaf, path, .. } = self;
        let (selection, file, archive) = source.into_stage_source();
        Ok((GenerationWorkspaceLease { selection, _parent: parent, root, leaf, path }, file, archive))
    }
    /// Exact fresh path retained for explicit failure reconciliation, never guessed cleanup.
    pub(crate) fn path(&self) -> &Path { &self.path }
}
impl GenerationWorkspaceLease {
    /// Retained parent for an exact-leaf security handle to this fresh workspace only.
    /// The parent itself is never a grant destination.
    pub(crate) fn workspace_parent(&self) -> &Dir { &self._parent }
    pub(crate) fn stage_parent(&self) -> &Dir { &self.root }
    pub(crate) const fn stage_name(&self) -> &'static str { "payload" }
    pub(crate) fn path(&self) -> &Path { &self.path }
    pub(crate) fn leaf(&self) -> &str { &self.leaf }
    pub(crate) fn source_selection(&self) -> &SelectedGenerationIdentity { &self.selection }
    pub(crate) fn retained_ancestors(&self) -> std::io::Result<Vec<Dir>> {
        let count = self.selection.ancestors().len().saturating_sub(1);
        self.selection.ancestors()[..count].iter().map(Dir::try_clone).collect()
    }
}

