//! One bounded ephemeral installer request, never persistent trust configuration.
use std::io::{Read as _, Seek as _, SeekFrom};
use std::path::{Path,PathBuf};
use std::sync::Arc;
use serde::Deserialize;
use keld_guard::windows_qualification_catalog::{DeploymentCatalogError,verify_catalog_for_windows_host};
use crate::baseline::windows_v3::VersionedBaselineVerifier;
use crate::UpdateError;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Request {
    schema:String,
    provenance:PathBuf,
    catalog:PathBuf,
    catalog_signature:PathBuf,
    manifest:PathBuf,
    manifest_signature:PathBuf,
    compressed_archive:PathBuf,
    canonical_content:PathBuf,
    release_public_key:[u8;32],
}
/// Typed underlying failures remain visible; no fallback or invented error-code claim.
#[derive(Debug)]
pub enum WindowsInitialInstallError {
    /// Existing current-image acquisition/verification refusal.
    Image(keld_guard::WindowsCurrentImageError),
    /// Compiled deployment policy or authenticated catalog refusal.
    Catalog(DeploymentCatalogError),
    /// Existing Update codec, authentication or protected filesystem refusal.
    Update(UpdateError),
    /// Bounded input read/shape refusal, before destination publication.
    Input(String),
}
impl std::fmt::Display for WindowsInitialInstallError {
    fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result {
        match self { Self::Image(e)=>write!(f,"initial install current image: {e:?}"),Self::Catalog(e)=>write!(f,"initial install catalog: {e:?}"),
            Self::Update(e)=>write!(f,"{e}"),Self::Input(e)=>write!(f,"initial install input: {e}") }
    }
}
impl std::error::Error for WindowsInitialInstallError {}
impl From<UpdateError> for WindowsInitialInstallError { fn from(e:UpdateError)->Self { Self::Update(e) } }

/// Runs explicit new-install V3 under this exact signed Host, never from an image path.
/// # Errors
/// Refuses unsupported authority, invalid inputs and any failed absent-only write/readback.
pub fn run_windows_initial_install_request(path:&Path) -> Result<super::v3::VersionedBaselineReceipt,WindowsInitialInstallError> {
    let (_request_pin,bytes)=read_input(path,64*1024)?;
    let request=parse_request(&bytes)?;
    // Exactly one current-image verification; never verify a caller's arbitrary path.
    let host=Arc::new(keld_guard::VerifiedCurrentWindowsImage::verify_current().map_err(WindowsInitialInstallError::Image)?);
    let (_catalog_pin,catalog_bytes)=read_input(&request.catalog,64*1024)?;
    let (_signature_pin,signature)=read_input(&request.catalog_signature,64)?;
    let signature:[u8;64]=signature.try_into().map_err(|_|input("catalog signature must be exactly 64 raw bytes"))?;
    let catalog=verify_catalog_for_windows_host(host,&catalog_bytes,&signature).map_err(WindowsInitialInstallError::Catalog)?;
    let (_provenance_pin,bytes)=read_input(&request.provenance,64*1024)?;
    let record=crate::records::profile_binding_v3::decode_windows_versioned_installation(&bytes)?;
    let verifier=VersionedBaselineVerifier::new(record,&catalog,&request.release_public_key)?;
    let (_manifest_pin,manifest)=read_input(&request.manifest,16*1024*1024)?;
    let (_manifest_signature_pin,signature)=read_input(&request.manifest_signature,256)?;
    let selected=verifier.verify_manifest(&manifest,&signature)?;
    let mut compressed=open_input(&request.compressed_archive)?;
    // No temporary extraction or filesystem sink. Verify compressed and content byte
    // domains, then the initializer independently revalidates canonical content.
    let verified=selected.verify_full(&mut compressed,&mut std::io::sink())?;
    let canonical=open_input(&request.canonical_content)?;
    // Keep canonical source pinned while initializer opens and verifies that same path.
    // The receipt's signed content digest is the authority, never this path or filename.
    let receipt=super::v3::initialize_versioned_per_user_baseline(&verified,&request.canonical_content,&catalog)?;
    drop(canonical);drop(compressed);
    Ok(receipt)
}
fn input(detail:impl Into<String>)->WindowsInitialInstallError { WindowsInitialInstallError::Input(detail.into()) }
fn open_input(path:&Path)->Result<cap_std::fs::File,WindowsInitialInstallError> {
    if !path.is_absolute() { return Err(input("installer locators must be absolute")); }
    crate::windows_extraction::open_source(path).map_err(|e|input(e.to_string()))
}
fn read_input(path:&Path,limit:u64)->Result<(cap_std::fs::File,Vec<u8>),WindowsInitialInstallError> {
    let mut pin=open_input(path)?;
    if pin.metadata().map_err(|e|input(e.to_string()))?.len()>limit { return Err(input("installer input exceeds bound")); }
    let mut bytes=Vec::new();
    pin.by_ref().take(limit+1).read_to_end(&mut bytes).map_err(|e|input(e.to_string()))?;
    if bytes.len() as u64>limit { return Err(input("installer input grew past bound")); }
    pin.seek(SeekFrom::Start(0)).map_err(|e|input(e.to_string()))?;
    Ok((pin,bytes))
}

fn parse_request(bytes:&[u8])->Result<Request,WindowsInitialInstallError> {
    if bytes.len()>64*1024 { return Err(input("request exceeds bound")); }
    let request:Request=serde_json::from_slice(bytes).map_err(|e|input(e.to_string()))?;
    if request.schema!="keld.windows-initial-install-request/v1" { return Err(input("unsupported request schema")); }
    Ok(request)
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn request_is_closed_bounded_and_not_persistent_authority() {
        let key=vec![0_u8;32];
        let good=serde_json::json!({"schema":"keld.windows-initial-install-request/v1",
            "provenance":"D:/in/provenance","catalog":"D:/in/catalog","catalog_signature":"D:/in/catalog.sig",
            "manifest":"D:/in/manifest","manifest_signature":"D:/in/manifest.sig",
            "compressed_archive":"D:/in/app.tar.zst","canonical_content":"D:/in/content.tar","release_public_key":key});
        let bytes=serde_json::to_vec(&good).unwrap();parse_request(&bytes).expect("shape only; grants no authority");
        let text=String::from_utf8(bytes).unwrap();
        let duplicate=text.replacen("\"schema\":","\"schema\":\"keld.windows-initial-install-request/v1\",\"schema\":",1);
        assert!(parse_request(duplicate.as_bytes()).is_err());
        let mut extra=good.clone();extra["allow_unverified"]=serde_json::json!(true);
        assert!(parse_request(&serde_json::to_vec(&extra).unwrap()).is_err());
        assert!(parse_request(text.replace("request/v1","request/v2").as_bytes()).is_err());
        assert!(parse_request(&vec![b' ';65537]).is_err());
        assert!(parse_request(b"{}").is_err());
    }
}

//! Absent-only new V3 PerUser baseline publication. No migration or update path.
use std::path::Path;
use keld_guard::windows_qualification_catalog::DeploymentQualifiedWindowsCatalog;
use crate::baseline::windows_v3::{VerifiedVersionedBaseline, require_catalog_binding};
use crate::windows_baseline::{RootLocation, RootHandles, open_root_handles, error, read_record,
    prepare_record, publish_prepared_record, RecordTarget};
use crate::UpdateError;
use super::{BaselineAuthority, acquire_bootstrap_lock_for, seed_activation_lock_for};

/// Retains verified initial-state readback; not current-image selection or a role permit.
#[derive(Debug)]
pub struct VersionedBaselineReceipt {
    _roots: RootHandles,
    _content: crate::windows_baseline::locate::v3::VersionedContent,
    _provenance: cap_std::fs::File,
    _catalog_pins: Vec<cap_std::fs::File>,
}

pub(crate) fn initialize_versioned_per_user_baseline(
    verified: &VerifiedVersionedBaseline,
    archive: &Path,
    catalog: &DeploymentQualifiedWindowsCatalog,
) -> Result<VersionedBaselineReceipt,UpdateError> {
    let record=verified.record();
    // All authority/identity checks precede creating any destination object.
    require_catalog_binding(record,catalog)?;
    keld_guard::require_windows_non_system_token().map_err(|e| error("installer authority",e))?;
    let mut source=crate::windows_extraction::open_source(archive).map_err(|e| error("baseline source admission",e))?;
    let validated=verified.validate_archive(&mut source)?;
    if validated.identity()!=verified.identity() || validated.content_size()!=verified.content_size() {
        return Err(error("versioned baseline","authenticated content identity differs"));
    }
    crate::baseline::windows_v3::require_archive_qualified_members(&validated,&source,catalog)?;
    let roots=open_root_handles(RootLocation { install_mode:record.install_mode,target:&record.target,
        install_root:&record.install_root,update_root:&record.update_root,volume_guid:&record.volume_guid },true)
        .map_err(|e| error("private scaffold admission",e))?;
    let install=roots.ancestors.last().ok_or_else(|| error("install root","absent"))?;
    let update_name=record.update_root.file_name().and_then(|x|x.to_str()).ok_or_else(||error("topology","update name absent"))?;
    let profile=record.install_mode.protection_profile();
    let lock=acquire_bootstrap_lock_for(install,&roots.update,&roots.versions,profile,update_name)?;
    seed_activation_lock_for(&roots.update,profile)?;
    super::publication::publish_validated_baseline(source,validated,&roots.versions,profile,BaselineAuthority::PerUser,&mut |_|Ok(()))?;
    super::publication::seed_initial_pointers(verified.identity(),&roots.update,profile,&mut |_|Ok(()))?;
    // Detached authenticated catalog avoids a self-reference with the archive digest.
    // Each absent-only sidecar precedes provenance. Partial publication is terminal,
    // not repairable implicitly on a subsequent initial-install attempt.
    let mut catalog_pins=Vec::new();
    for (name,bytes) in [
        (crate::windows_baseline::locate::v3::CATALOG,catalog.catalog().signed_bytes()),
        (crate::windows_baseline::locate::v3::CATALOG_SIGNATURE,catalog.catalog().signature().as_slice()),
    ] {
        let pending=prepare_record(install,bytes,profile)?;
        publish_prepared_record(install,&pending,RecordTarget::Absent(name),bytes,profile)?;
        let (pin,actual)=read_record(install,name,profile)?;
        if actual!=bytes { return Err(error("catalog sidecar readback","exact published bytes differ")); }
        catalog_pins.push(pin);
    }
    let bytes=crate::records::profile_binding_v3::encode_windows_versioned_installation(record)?;
    let pending=prepare_record(install,&bytes,profile)?;
    lock.sync_all().map_err(|e|error("bootstrap lock flush",e))?;
    keld_guard::validate_windows_install_file(&lock,profile).map_err(|e|error("bootstrap lock profile",e))?;
    // Provenance is still the final commit record; never replace an existing record.
    publish_prepared_record(install,&pending,RecordTarget::Absent("install-provenance"),&bytes,profile)?;
    drop(lock);
    let (provenance,actual)=read_record(install,"install-provenance",profile)?;
    if actual!=bytes { return Err(error("versioned provenance readback","exact published bytes differ")); }
    let content=crate::windows_baseline::locate::v3::read_initial_source(record,&roots)?;
    Ok(VersionedBaselineReceipt { _roots:roots,_content:content,_provenance:provenance,_catalog_pins:catalog_pins })
}

