//! Explicit protected initial-baseline V3 selection. Never v2 fallback or repair.
use cap_std::fs::{Dir, File};
use std::sync::Arc;
use keld_guard::VerifiedCurrentWindowsImage;
use keld_guard::windows_qualification_catalog::{DeploymentQualifiedWindowsCatalog, verify_catalog_for_windows_host};
use super::{Located, LocatedLayout, ObjectIdentity, PROVENANCE, binding, open_image};
use crate::{ArtifactIdentity, UpdateError, WindowsLocatedImage};
use crate::provenance::WindowsVersionedInstallationRecord as Record;
use crate::windows_baseline::{RootHandles, RootLocation, admit_machine_file, error,
    exact_entries, open_pinned_leaf, open_root_handles, read_open_record, read_record};
use crate::records::{self, PointerKind};

pub(in crate::windows_baseline) const CATALOG: &str = "qualification-catalog.v1";
pub(in crate::windows_baseline) const CATALOG_SIGNATURE: &str = "qualification-catalog.v1.sig";

fn install_entries(update_name: &str) -> [&str;4] { [update_name,PROVENANCE,CATALOG,CATALOG_SIGNATURE] }

fn open_v3(host: &VerifiedCurrentWindowsImage) -> Result<Located, UpdateError> {
    let image=WindowsLocatedImage::Host;
    let layout=LocatedLayout::parse(image,host.locator())?;
    let executable=ObjectIdentity::of_file(host.image().file()).map_err(|e|binding(image,"executable handle",e))?;
    let volume=crate::windows_fs::qualified_volume_root(host.image().file()).map_err(|e|binding(image,"executable volume",e))?;
    Located::open_with_entries(image,&layout,&volume,&executable,
        &install_entries(&layout.update_name))
}

/// Installed boot uses only fixed protected sidecars and the same verified current Host.
/// The signature is reauthenticated by the existing single catalog verifier, not a
/// caller-selected authority. All pins survive in the returned selected source.
pub(crate) fn locate_versioned_initial_baseline(
    host: Arc<VerifiedCurrentWindowsImage>,
) -> Result<(VersionedBaselineSelection, DeploymentQualifiedWindowsCatalog),UpdateError> {
    let located=open_v3(&host)?;
    let (provenance,bytes)=read_open_record(open_pinned_leaf(located.install()?,PROVENANCE).map_err(|e|error("protected provenance",e))?)?;
    let record=records::profile_binding_v3::decode_windows_versioned_installation(&bytes)?;
    let profile=record.install_mode.protection_profile();
    admit_machine_file(located.install()?,&cap_std::io_lifetimes::AsFilelike::as_filelike_view::<std::fs::File>(&provenance),profile)
        .map_err(|e|error("protected provenance profile",e))?;
    let (catalog_pin,payload)=read_record(located.install()?,CATALOG,profile)?;
    let (signature_pin,signature)=read_record(located.install()?,CATALOG_SIGNATURE,profile)?;
    let signature: [u8;64]=signature.try_into().map_err(|_|error("catalog signature","expected exactly 64 raw bytes"))?;
    let catalog=verify_catalog_for_windows_host(Arc::clone(&host),&payload,&signature)
        .map_err(|e|error("protected catalog authentication",e))?;
    crate::baseline::windows_v3::require_catalog_binding(&record,&catalog)?;
    let mut selected=select_versioned_initial_baseline(&host,&catalog)?;
    if selected.record()!=&record { return Err(error("protected selection","record changed during selection")); }
    selected.records.extend([provenance,catalog_pin,signature_pin]);
    Ok((selected,catalog))
}

/// Actual protected record, complete authenticated archive and retained ancestry.
/// Private fields, no Clone, no conversion into v2 identity or update authority.
#[derive(Debug)]
pub(crate) struct VersionedBaselineSelection {
    record: Record,
    roots: RootHandles,
    _version: Dir,
    tree: Dir,
    source: File,
    archive: crate::ValidatedArchive,
    records: Vec<File>,
}
impl VersionedBaselineSelection {
    pub(crate) fn artifact(&self) -> &ArtifactIdentity { &self.record.baseline }
    pub(crate) fn record(&self) -> &Record { &self.record }
    pub(in crate::windows_baseline) fn ancestors(&self) -> &[Dir] { &self.roots.ancestors }
    pub(in crate::windows_baseline) fn retained_source(&self) -> &File { &self.source }
    pub(in crate::windows_baseline) fn archive(&self) -> &crate::ValidatedArchive { &self.archive }

}

pub(crate) fn select_versioned_initial_baseline<'catalog, 'host>(
    host: &'host VerifiedCurrentWindowsImage,
    catalog: &'catalog DeploymentQualifiedWindowsCatalog,
) -> Result<VersionedBaselineSelection, UpdateError> {
    if !std::ptr::eq(host.image(), catalog.host()) {
        return Err(error("versioned selection", "catalog belongs to another current-image owner"));
    }
    let image = WindowsLocatedImage::Host;
    let layout = LocatedLayout::parse(image, host.locator())?;
    let executable = ObjectIdentity::of_file(host.image().file()).map_err(|e| binding(image,"executable handle",e))?;
    let volume = crate::windows_fs::qualified_volume_root(host.image().file())
        .map_err(|e| binding(image,"executable volume",e))?;
    let located = open_v3(host)?;
    let file = open_pinned_leaf(located.install()?, PROVENANCE).map_err(|e| error("protected record open",e))?;
    let (file, bytes) = read_open_record(file)?;
    // Explicit closed v3 decoder. No parse-error fallback to another schema.
    let record = records::profile_binding_v3::decode_windows_versioned_installation(&bytes)?;
    let profile = record.install_mode.protection_profile();
    admit_machine_file(located.install()?, &cap_std::io_lifetimes::AsFilelike::as_filelike_view::<std::fs::File>(&file),profile)
        .map_err(|e| error("protected record profile",e))?;
    crate::baseline::windows_v3::require_catalog_binding(&record,catalog)?;
    if !record.volume_guid.eq_ignore_ascii_case(&volume) || layout.version != record.baseline.version {
        return Err(binding(image,"versioned record binding","volume or located version differs"));
    }
    let roots = open_root_handles(RootLocation { install_mode:record.install_mode,target:&record.target,
        install_root:&record.install_root,update_root:&record.update_root,volume_guid:&record.volume_guid },false)
        .map_err(|e| error("recorded roots",e))?;
    let install = roots.ancestors.last().ok_or_else(|| error("recorded roots","install root absent"))?;
    for (recorded, actual) in [(install,located.install()?),(&roots.update,&located.update),(&roots.versions,&located.versions)] {
        if ObjectIdentity::of_dir(recorded).map_err(|e| error("recorded roots",e))?
            != ObjectIdentity::of_dir(actual).map_err(|e| error("located roots",e))? {
            return Err(binding(image,"recorded root identity","recorded root differs from located object"));
        }
    }
    let VersionedContent { version, tree, source, archive, mut records } = read_initial_source(&record,&roots)?;
    let selected_image = open_image(&tree,image).map_err(|e| error("selected current image",e))?;
    if ObjectIdentity::of_cap_file(&selected_image).map_err(|e| error("selected current image",e))? != executable {
        return Err(binding(image,"selected current image","selected Host differs from actual retained current image"));
    }
    records.push(selected_image); records.push(file);
    drop(located);
    Ok(VersionedBaselineSelection { record,roots,_version:version,tree,source,archive,records })
}

#[derive(Debug)]
pub(in crate::windows_baseline) struct VersionedContent {
    version: Dir, tree: Dir, source: File, archive: crate::ValidatedArchive, records: Vec<File>,
}
/// Shared strict initial-state reader for initializer readback and current-image selection.
/// Returning byte custody alone conveys no selected/protected installation authority.
pub(in crate::windows_baseline) fn read_initial_source(record:&Record, roots:&RootHandles) -> Result<VersionedContent,UpdateError> {
    let profile = record.install_mode.protection_profile();
    let lease = crate::windows_baseline::open_activation_lease(&roots.update,profile,false)
        .map_err(|e| error("versioned snapshot lease",e))?;
    exact_entries(&roots.update,&["versions","activation.lock","bootstrap.lock","version-floor","current","last-known-good"])
        .map_err(|e| error("versioned initial state",e))?;
    exact_entries(&roots.versions,&[&record.baseline.version]).map_err(|e| error("versioned initial versions",e))?;
    let mut records = Vec::new();
    let (bootstrap, bootstrap_bytes) = read_record(&roots.update,"bootstrap.lock",profile)?;
    if !bootstrap_bytes.is_empty() { return Err(error("initial lock","bootstrap marker is not empty")); }
    records.push(bootstrap);
    let (floor, bytes) = read_record(&roots.update,"version-floor",profile)?;
    if records::decode_floor(&bytes)? != record.baseline.version { return Err(error("initial floor","floor differs from baseline")); }
    records.push(floor);
    for (name,kind) in [("current",PointerKind::Current),("last-known-good",PointerKind::LastKnownGood)] {
        let (pin,bytes) = read_record(&roots.update,name,profile)?;
        if records::decode_pointer(kind,&bytes)? != record.baseline { return Err(error("initial pointer","pointer differs from baseline")); }
        records.push(pin);
    }
    let completion = crate::windows_baseline::load::read_version_completion_from_parts(&roots.versions,profile,&record.baseline)?;
    crate::windows_baseline::load::validate_package_policy_for(&completion.tree,profile)?;
    let content = crate::full::ContentIdentity { identity:record.baseline.clone(),
        content_size:completion.record.content_size,content_blake3:record.baseline.content_blake3 };
    let mut source=completion.content;
    let archive=crate::archive::parse_content_archive(&content,&mut source,keld_guard::validate_windows_package_paths)?;
    records.push(completion.marker);
    drop(lease);
    Ok(VersionedContent { version:completion.version,tree:completion.tree,source,archive,records })
}
