mod sidecar_layout_tests {
    use super::*;
    #[test]
    fn closed_layout_refuses_missing_partial_and_extra_publication() {
        let temporary=tempfile::tempdir().unwrap();
        let directory=Dir::open_ambient_dir(temporary.path(),cap_std::ambient_authority()).unwrap();
        directory.create_dir("update").unwrap();
        // Every partial prefix refuses, including catalog written without signature
        // and both sidecars written without the final provenance commit record.
        assert!(exact_entries(&directory,&install_entries("update")).is_err());
        for name in [CATALOG,CATALOG_SIGNATURE] {
            drop(directory.create(name).unwrap());
            assert!(exact_entries(&directory,&install_entries("update")).is_err());
        }
        drop(directory.create(PROVENANCE).unwrap());
        exact_entries(&directory,&install_entries("update")).unwrap();
        // A V3 installation cannot enter the unchanged closed V2 layout.
        assert!(exact_entries(&directory,&["update",PROVENANCE]).is_err());
        drop(directory.create("unexpected").unwrap());
        assert!(exact_entries(&directory,&install_entries("update")).is_err());
    }
}

/// Read-only installed boot view, distinct from the legacy exact-profile selection.
/// Keeps the same protected V3 selection and actual qualified Bun image pinned.
/// This is neither a staged generation nor a Strict/spawn permit.
#[derive(Debug)]
pub struct QualifiedWindowsBootView {
    selection: Arc<VersionedBaselineSelection>,
    tree_root: std::path::PathBuf,
    runtime_path: std::path::PathBuf,
    runtime: std::fs::File,
}
impl QualifiedWindowsBootView {
    /// Protected selected tree locator with retained object ancestry.
    /// This does not assert global namespace/content immutability.
    #[must_use]
    pub fn tree_root(&self) -> &std::path::Path { &self.tree_root }
    /// Actual protected installation mode, not a caller's boot preference.
    #[must_use]
    pub fn install_mode(&self) -> crate::DirectInstallMode { self.selection.record.install_mode }
    /// Canonical Bun member under this retained selected tree; never PATH resolution.
    #[must_use]
    pub fn runtime_path(&self) -> &std::path::Path { &self.runtime_path }
    /// Actual protected read-sharing Bun handle whose bytes matched the catalog.
    #[must_use]
    pub fn runtime_file(&self) -> &std::fs::File { &self.runtime }
}
impl VersionedBaselineSelection {
    pub(crate) fn boot_view(self:&Arc<Self>,catalog:&DeploymentQualifiedWindowsCatalog)
        -> Result<QualifiedWindowsBootView,UpdateError> {
        crate::baseline::windows_v3::require_catalog_binding(&self.record,catalog)?;
        let recipe=catalog.primary_read_recipe();
        let runtime=crate::windows_baseline::open_machine_file(&self.tree,recipe.runtime_member(),
            self.record.install_mode.protection_profile()).map_err(|e|error("qualified boot runtime",e))?.into_std();
        let length=runtime.metadata().map_err(|e|error("qualified runtime size",e))?.len();
        // Reuse the same positional digest owner. A standalone image occupies its
        // whole file; no new verifier, caller digest, or shared cursor assumption.
        crate::baseline::windows_v3::require_member_digest(&runtime,0,length,length,
            recipe.runtime_artifact_digest().0)?;
        let tree_root=self.record.update_root.join("versions").join(&self.record.baseline.version).join("tree");
        let runtime_path=tree_root.join(recipe.runtime_member());
        Ok(QualifiedWindowsBootView {selection:Arc::clone(self),tree_root,runtime_path,runtime})
    }
}

