fn selected_generation_source_keeps_complete_inventory_and_ancestry() {
    use std::io::{Read as _, Seek as _, SeekFrom};
    support::assert_user_principal_token();
    let (temp, trust, source) = fixture();
    let verified = support::baseline(&trust);
    let initialized = initialize_windows_per_user_baseline(&verified, &source, &trust)
        .expect("initialize exact fixture bytes");
    drop(initialized);
    let selection = std::sync::Arc::new(crate::windows_baseline::select_windows_active_package(&trust)
        .expect("select protected fixture"));
    let selected = selection.open_generation_source().expect("complete selected archive");
    drop(selection);
    let (retained_selection, mut content, inventory) = selected.into_stage_source();
    assert_eq!(inventory.identity(), retained_selection.artifact());
    assert_eq!(inventory.content_size(), GOLDEN.len() as u64);
    assert!(!inventory.entries().is_empty());
    let expected = verified.validate_windows_archive(&mut std::io::Cursor::new(GOLDEN))
        .expect("existing parser independently supplied canonical fixture");
    assert_eq!(inventory.entries(), expected.entries());
    content.seek(SeekFrom::Start(0)).expect("rewind retained source");
    let mut actual=Vec::new(); content.read_to_end(&mut actual).expect("retained source bytes");
    assert_eq!(actual, GOLDEN);
    let moved = temp.path().join("moved-update");
    let rename_error = fs::rename(&trust.installation.update_root, &moved)
        .expect_err("source capability must retain selected ancestors");
    assert_eq!(rename_error.raw_os_error(), Some(32), "actual sharing violation");
    drop(content); drop(retained_selection);
    fs::rename(&trust.installation.update_root, &moved).expect("rename succeeds after custody release");
    fs::rename(&moved, &trust.installation.update_root).expect("restore exact owned fixture path");
    temp.close().expect("exact owned fixture cleanup");
}

#[test]
#[ignore = "operator acceptance: same-size tamper of an exact owned per-user fixture only"]
fn selected_generation_source_refuses_same_size_payload_tamper() {
    use std::io::{Seek as _, SeekFrom};
    support::assert_user_principal_token();
    let (temp, trust, source) = fixture();
    let verified = support::baseline(&trust);
    let initialized = initialize_windows_per_user_baseline(&verified, &source, &trust)
        .expect("initialize exact fixture");
    drop(initialized);
    let selection = std::sync::Arc::new(crate::windows_baseline::select_windows_active_package(&trust)
        .expect("select before tampering"));
    let inventory = verified.validate_windows_archive(&mut std::io::Cursor::new(GOLDEN))
        .expect("original complete fixture");
    let entry = inventory.entries().iter().find(|entry| entry.name() == "nest/one")
        .expect("plain non-policy payload fixture");
    assert!(entry.size() > 0);
    let offset = usize::try_from(entry.data_offset()).expect("fixture offset");
    let content_path = trust.installation.update_root.join("versions/1.0.0/content.tar");
    let before_length = fs::metadata(&content_path).expect("source length").len();
    let mut writer = fs::OpenOptions::new().write(true).open(&content_path)
        .expect("owner can write exact unpinned fixture source");
    writer.seek(SeekFrom::Start(entry.data_offset())).expect("payload offset");
    writer.write_all(&[GOLDEN[offset] ^ 1]).expect("same-size payload mutation");
    writer.sync_all().expect("flush exact mutation"); drop(writer);
    assert_eq!(fs::metadata(&content_path).expect("mutated length").len(), before_length);
    let error = selection.open_generation_source().expect_err("selected digest must bind source bytes");
    assert!(matches!(error, UpdateError::ArtifactDigestMismatch { .. }), "{error:?}");
    drop(selection);
    temp.close().expect("remove exact owned mutated fixture");
}

