//! Proposed child of windows_extraction::tests, using its existing test authority.
use super::{Fixture, GOLDEN_TAR};
use crate::windows_generation_stage::UnsealedGenerationStage;
use cap_std::{ambient_authority, fs::Dir};

fn stage(fixture: &Fixture, name: &str) -> UnsealedGenerationStage {
    let source_path = fixture.source(GOLDEN_TAR);
    let mut source = crate::windows_extraction::open_source(&source_path).expect("retained fixture source");
    let archive = fixture.receipt(GOLDEN_TAR).validate_windows_archive(&mut source)
        .expect("actual authenticated archive parser");
    let parent = Dir::open_ambient_dir(fixture.versions(), ambient_authority()).expect("fixture parent");
    UnsealedGenerationStage::materialize_fixture(parent, Vec::new(), source, archive, name.to_owned())
        .expect("materialize every authenticated member")
}

#[test]
fn complete_inventory_retains_payload_against_write_delete_and_rename() {
    let fixture = Fixture::new();
    let stage = stage(&fixture, "generation-test");
    stage.check_inventory().expect("complete actual namespace");
    let root = fixture.versions().join("generation-test");
    let mut pending = vec![root.clone()];
    let mut members = Vec::new();
    while let Some(directory) = pending.pop() {
        for entry in std::fs::read_dir(directory).expect("test census") {
            let entry = entry.expect("test entry");
            if entry.file_type().expect("test type").is_dir() { pending.push(entry.path()); }
            else { members.push(entry.path()); }
        }
    }
    assert!(members.len() > 1, "actual package members, not only content.tar");
    for member in &members {
        for error in [
            std::fs::OpenOptions::new().write(true).open(member).expect_err("retained writer denial"),
            std::fs::remove_file(member).expect_err("retained delete denial"),
            std::fs::rename(member, member.with_extension("moved")).expect_err("retained rename denial"),
        ] { assert_eq!(error.raw_os_error(), Some(32)); }
    }
    assert_eq!(std::fs::rename(&root, root.with_extension("moved")).expect_err("root retained").raw_os_error(), Some(32));
    drop(stage);
    for member in members {
        drop(std::fs::OpenOptions::new().write(true).open(&member).expect("post-release writer positive"));
        let moved = member.with_extension("released-move");
        std::fs::rename(&member, &moved).expect("post-release rename positive");
        std::fs::remove_file(moved).expect("post-release delete positive");
    }
}

