    let parent = Dir::open_ambient_dir(fixture.versions(), ambient_authority()).expect("parent");
    let failure = UnsealedGenerationStage::materialize_fixture(parent, Vec::new(), source, archive, "generation-test".into())
        .expect_err("authenticated digest must be rechecked before materializing members");
    assert!(failure.detail.contains("BLAKE3") || failure.detail.contains("digest"));
    assert!(!fixture.versions().join("generation-test/tree").exists());
    drop(failure);
}

//! Authenticated, complete-inventory materialization precursor. Not launch authority.
//!
//! Kept private to Update until a selected-package inventory/ancestry owner is
//! connected. No profile, ACL grant, admission, process or installation publication.
use std::collections::BTreeMap;
use std::io;

use cap_fs_ext::MetadataExt as _;
use cap_std::fs::{Dir, File};
use crate::{ArchiveEntryKind, ValidatedArchive};
use crate::windows_extraction::{StageProtection, populate_stage};

/// All successful destination objects and the authenticated source stay owned.
/// Directory creation handles are NOT sealed against future write opens.
#[derive(Debug)]
pub(crate) struct UnsealedGenerationStage {
    source_custody: GenerationSourceCustody,
    parent: Dir,
    ancestors: Vec<Dir>,
    source: File,
    archive: ValidatedArchive,
    directories: Vec<Dir>,
    files: Vec<File>,
    name: String,
}

/// Production source provenance stays retained; fixture authority cannot be
/// promoted through a production constructor.
#[derive(Debug)]
enum GenerationSourceCustody {
    Workspace(crate::windows_baseline::GenerationWorkspaceLease),
    #[cfg(test)]
    SyntheticFixture,
}

/// A failed attempt preserves its parent and surviving pins for quarantine.
/// Materialization retains its new root; a failed seal may have released it.
/// No automatic deletion, retry, install publication or grant follows failure.
#[derive(Debug)]
pub(crate) struct GenerationStageFailure {
    pub(crate) detail: String,
    pub(crate) stage: UnsealedGenerationStage,
}

#[derive(Debug)]
pub(crate) struct ReadyGenerationInputs {
    workspace: crate::windows_baseline::GenerationWorkspaceLease,
    source: File,
    archive: ValidatedArchive,
}

#[derive(Debug)]
pub(crate) enum GenerationPreparationFailure {
    Unready(crate::windows_baseline::PreparedGenerationInputs),
    BeforeStage { detail: String, inputs: Box<ReadyGenerationInputs> },
    Stage(GenerationStageFailure),
}

impl UnsealedGenerationStage {
    /// Consumes only selected-source-derived, successfully prepared workspace
    /// inputs. No caller parent, ancestor chain, source pair or leaf is accepted.
    pub(crate) fn materialize(
        inputs: crate::windows_baseline::PreparedGenerationInputs,
    ) -> Result<Self, GenerationPreparationFailure> {
        let (workspace, source, archive) = inputs.into_stage_parts()
            .map_err(GenerationPreparationFailure::Unready)?;
        let ready = ReadyGenerationInputs { workspace, source, archive };
        let parent = match ready.workspace.stage_parent().try_clone() {
            Ok(parent) => parent,
            Err(error) => return Err(GenerationPreparationFailure::BeforeStage {
                detail: error.to_string(), inputs: Box::new(ready),
            }),
        };
        let ancestors = match ready.workspace.retained_ancestors() {
            Ok(ancestors) => ancestors,
            Err(error) => return Err(GenerationPreparationFailure::BeforeStage {
                detail: error.to_string(), inputs: Box::new(ready),
            }),
        };
        let name = ready.workspace.stage_name().to_owned();
        let ReadyGenerationInputs { workspace, source, archive } = ready;
        Self::materialize_parts(parent, ancestors, source, archive, name,
            GenerationSourceCustody::Workspace(workspace)).map_err(GenerationPreparationFailure::Stage)
    }

    #[cfg(test)]
    pub(crate) fn materialize_fixture(
        parent: Dir, ancestors: Vec<Dir>, source: File,
        archive: ValidatedArchive, name: String,
    ) -> Result<Self, GenerationStageFailure> {
        Self::materialize_parts(parent, ancestors, source, archive, name,
            GenerationSourceCustody::SyntheticFixture)
    }

    fn materialize_parts(
        parent: Dir, ancestors: Vec<Dir>, source: File,
        archive: ValidatedArchive, name: String, source_custody: GenerationSourceCustody,
    ) -> Result<Self, GenerationStageFailure> {
        let mut stage = Self {
            source_custody, parent, ancestors, source, archive, name,
            directories: Vec::new(), files: Vec::new(),
        };
        match stage.fill() {
            Ok(()) => Ok(stage),
            Err(error) => Err(GenerationStageFailure { detail: error.to_string(), stage }),
        }
    }

    fn fill(&mut self) -> io::Result<()> {
        // Relative NT creation owns component validation, absent-only creation,
        // no-reparse semantics, volume support and the private descriptor.
        let parent = self.parent.try_clone()?.into_std_file();
        crate::windows_fs::qualify_volume(&parent)?;
        keld_guard::validate_windows_owner_private_directory(&parent)?;
        let volume = self.parent.dir_metadata()?.dev();
        for ancestor in &self.ancestors {
            let metadata = ancestor.dir_metadata()?;
            crate::windows_extraction::ensure_directory(&metadata)?;
            if metadata.dev() != volume {
                return Err(io::Error::other("generation ancestor crosses volume"));
            }
        }
        let root = crate::windows_fs::create_directory_relative(&parent, &self.name)?;
        // Keep an independent root handle even if the existing extractor fails
        // and releases its partial descendants. Partial bytes remain quarantined.
        self.directories.push(Dir::from_std_file(root));
        let extractor_root = self.directories[0].try_clone()?.into_std_file();
        let (directories, files) = populate_stage(
            extractor_root, &self.name, &self.archive, &mut self.source,
            StageProtection::OwnerPrivate, &mut |_, _| Ok(()),
        ).map_err(io::Error::other)?;
        self.directories = directories;
        self.files = files;
        self.check_inventory()
    }

    /// Recheck the actual complete namespace, not a fixed Bun/main/transport list.
    /// A successful check still supplies no sealed namespace or launch permit.
    pub(crate) fn check_inventory(&self) -> io::Result<()> {
        let mut expected = BTreeMap::<String, Vec<String>>::from([
            (String::new(), vec!["content.tar".into(), "tree".into()]),
            ("tree".into(), Vec::new()),
        ]);
        let mut directory_names = vec![String::new(), "tree".into()];
        let mut file_sizes = Vec::new();
        for entry in self.archive.entries() {
            let (parent, leaf) = entry.name().rsplit_once('/').unwrap_or(("", entry.name()));
            let parent = if parent.is_empty() { "tree".into() } else { format!("tree/{parent}") };
            expected.get_mut(&parent).ok_or_else(|| io::Error::other("authenticated inventory parent absent"))?
                .push(leaf.to_owned());
            match entry.kind() {
                ArchiveEntryKind::Directory => {
                    let name = format!("tree/{}", entry.name());
                    if expected.insert(name.clone(), Vec::new()).is_some() {
                        return Err(io::Error::other("duplicate authenticated directory"));
                    }
                    directory_names.push(name);
                }
                ArchiveEntryKind::File => file_sizes.push(entry.size()),
            }
        }
        file_sizes.push(self.archive.content_size());
        if self.directories.len() != directory_names.len() || self.files.len() != file_sizes.len() {
            return Err(io::Error::other("retained inventory cardinality changed"));
        }
        let volume = self.parent.dir_metadata()?.dev();
        for (directory, name) in self.directories.iter().zip(directory_names) {
            let metadata = directory.dir_metadata()?;
            crate::windows_extraction::ensure_directory(&metadata)?;
            if metadata.dev() != volume { return Err(io::Error::other("directory crosses volume")); }
            let actual = crate::windows_fs::child_names(&directory.try_clone()?.into_std_file())?;
            exact_children(&expected[&name], actual)?;
        }
        for (file, size) in self.files.iter().zip(file_sizes) {
            let metadata = file.metadata()?;
            crate::windows_extraction::ensure_regular(&metadata)?;
            if metadata.dev() != volume || metadata.len() != size {
                return Err(io::Error::other("retained file volume or size changed"));
            }
        }
        Ok(())
    }
}

fn exact_children(expected: &[String], mut actual: Vec<String>) -> io::Result<()> {
    let mut expected = expected.to_vec();
    expected.sort();
    actual.sort();
    if expected != actual { return Err(io::Error::other("missing or surplus generation member")); }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::exact_children;
    #[test]
    fn census_refuses_missing_surplus_and_case_substitution() {
        let names = vec!["main.js".to_owned(), "kipc-transport.js".to_owned()];
        assert!(exact_children(&names, names.iter().rev().cloned().collect()).is_ok());
        assert!(exact_children(&names, vec!["main.js".into()]).is_err());
        assert!(exact_children(&names, vec!["main.js".into(), "kipc-transport.js".into(), "extra.js".into()]).is_err());
        assert!(exact_children(&names, vec!["MAIN.js".into(), "kipc-transport.js".into()]).is_err());
        assert!(exact_children(&names, vec!["main.js".into(), "main.js".into()]).is_err());
    }
}

