/// Historical observations only; all security-writable handles are closed.
/// Original destination data/read pins remain in UnsealedGenerationStage.
#[derive(Debug)]
pub(super) struct AppliedMemberGrant {
    pub(super) member: String,
    pub(super) grant: keld_guard::WindowsGenerationGrantedMember,
}

/// One successful transition binds this exact stage to one live registration.
/// No API returns the ungranted stage or accepts another registration.
#[derive(Debug)]
pub(super) struct GrantedGenerationStage {
    stage: UnsealedGenerationStage,
    registration: std::rc::Rc<WindowsProfileRegistration>,
    catalog: std::sync::Arc<DeploymentQualifiedWindowsCatalog>,
    observations: Vec<AppliedMemberGrant>,
    data: super::role_data::RoleDataDirectory,
    installation: super::installation_binding::SelectedInstallationBinding,
    claim:keld_guard::WindowsGenerationGrantClaim,
}

/// Failed transitions retain resources/progress without a retry conversion.
#[derive(Debug)]
pub(super) struct GenerationGrantFailure {
    registration: std::rc::Rc<WindowsProfileRegistration>,
    catalog: std::sync::Arc<DeploymentQualifiedWindowsCatalog>,
    error: String,
    stage: UnsealedGenerationStage,
    observations: Vec<AppliedMemberGrant>,
    attempted: Option<String>,
    data_failure: Option<super::role_data::RoleDataFailure>,
    failed_grant: Option<GrantEvidenceFailure>,
    claim:Option<keld_guard::WindowsGenerationGrantClaim>,
    claim_failure:Option<keld_guard::WindowsGenerationClaimFailure>,
}

impl UnsealedGenerationStage {
    pub(super) fn grant_for_catalog(
        self,
        registration: std::rc::Rc<WindowsProfileRegistration>,
        catalog: std::sync::Arc<DeploymentQualifiedWindowsCatalog>,
    ) -> Result<GrantedGenerationStage, GenerationGrantFailure> {
        let plan = match super::read_plan::derive(&self, &catalog) {
            Ok(readable) => readable,
            Err(error) => return Err(GenerationGrantFailure {
                registration, catalog, error: error.to_string(), stage: self,
                observations: Vec::new(), attempted: Some("deployment-read-plan".to_owned()), data_failure: None, failed_grant: None, claim:None, claim_failure:None,
            }),
        };
        let super::read_plan::ReadPlan { readable, installation } = plan;
        let roles=match planned_roles(&self) {
            Ok(roles)=>roles,
            Err(error)=>return Err(GenerationGrantFailure { registration,catalog,error:error.to_string(),stage:self,
                observations:Vec::new(),attempted:Some("resource-role-plan".into()),data_failure:None,failed_grant:None,claim:None,claim_failure:None }),
        };
        let mut claim=match keld_guard::WindowsGenerationGrantClaim::reserve(std::rc::Rc::clone(&registration),std::sync::Arc::clone(&catalog),roles) {
            Ok(claim)=>claim,
            Err(failure)=>return Err(GenerationGrantFailure { registration,catalog,error:failure.detail().to_owned(),stage:self,
                observations:Vec::new(),attempted:Some("pre-write-generation-claim".into()),data_failure:None,failed_grant:None,claim:None,claim_failure:Some(failure) }),
        };
        let mut observations = Vec::new();
        let mut attempted = None;
        if let Err(error) = self.apply_read_members(&mut claim, &readable, &mut observations, &mut attempted) {
            return Err(GenerationGrantFailure {
                registration, catalog, error: error.error.to_string(), stage: self, observations, attempted, data_failure: None, failed_grant: error.custody,claim:Some(claim),claim_failure:None,
            });
        }
        match self.prepare_role_data(&mut claim) {
            Ok(data) => Ok(GrantedGenerationStage { stage: self, registration, catalog, observations, data, installation, claim }),
            Err(failure) => Err(GenerationGrantFailure {
                registration, catalog, error: "role-data preparation failed; preserve partial resources".to_owned(),
                stage: self, observations, attempted: Some("role-data".to_owned()), data_failure: Some(failure), failed_grant: None,claim:Some(claim),claim_failure:None,
            }),
        }
    }

    fn apply_read_members(
        &self,
        claim: &mut keld_guard::WindowsGenerationGrantClaim,
        readable: &BTreeSet<String>,
        observations: &mut Vec<AppliedMemberGrant>,
        attempted: &mut Option<String>,
    ) -> Result<(), GrantAttemptError> {
        *attempted = Some("inventory-preflight".to_owned());
        self.check_inventory()?;
        let files: Vec<_> = self.archive.entries().iter()
            .filter(|entry| entry.kind() == crate::ArchiveEntryKind::File).collect();
        if readable.iter().any(|name| !files.iter().any(|entry| entry.name() == name)) {
            return Err(io::Error::other("grant references a non-file or absent authenticated member").into());
        }
        *attempted = Some("fresh-workspace-traverse".to_owned());
        let workspace = match &self.source_custody {
            super::GenerationSourceCustody::Workspace(workspace) => workspace,
            #[cfg(test)]
            super::GenerationSourceCustody::SyntheticFixture => return Err(io::Error::other(
                "granting requires a selected-source-derived workspace").into()),
        };
        let workspace_root = workspace.stage_parent().try_clone()?.into_std_file();
        observations.push(publish(claim, workspace.workspace_parent(), workspace.leaf(),
            &workspace_root, "<workspace>", WindowsProfilePathAccess::Traverse)?);
        // The root and every canonical directory are traversable only, never
        // recursively read/write granted. Explicit member reads follow below.
        let mut directory_names = vec![String::new(), "tree".to_owned()];
        directory_names.extend(self.archive.entries().iter()
            .filter(|entry| entry.kind() == crate::ArchiveEntryKind::Directory)
            .map(|entry| format!("tree/{}", entry.name())));
        for (index, name) in directory_names.iter().enumerate() {
            *attempted = Some(name.clone());
            let (parent, leaf) = if index == 0 {
                (&self.parent, self.name.as_str())
            } else {
                let (parent_name, leaf) = name.rsplit_once('/').unwrap_or(("", name));
                let parent_index = directory_names.iter().position(|item| item == parent_name)
                    .ok_or_else(|| io::Error::other("retained directory parent absent"))?;
                (&self.directories[parent_index], leaf)
            };
            let original = self.directories[index].try_clone()?.into_std_file();
            observations.push(publish(claim, parent, leaf, &original, name,
                WindowsProfilePathAccess::Traverse)?);
        }
        for (index, entry) in files.iter().enumerate() {
            if !readable.contains(entry.name()) { continue; }
            *attempted = Some(entry.name().to_owned());
            let (parent_name, leaf) = entry.name().rsplit_once('/').unwrap_or(("", entry.name()));
            let parent_name = if parent_name.is_empty() { "tree".into() } else { format!("tree/{parent_name}") };
            let parent_index = directory_names.iter().position(|item| item == &parent_name)
                .ok_or_else(|| io::Error::other("retained file parent absent"))?;
            let original = self.files[index].try_clone()?.into_std();
            observations.push(publish(claim, &self.directories[parent_index], leaf,
                &original, entry.name(), WindowsProfilePathAccess::ReadExecute)?);
        }
        *attempted = Some("inventory-postgrant".to_owned());
        self.check_inventory()?;
        *attempted = None;
        Ok(())
    }
}

/// Failed native writer or retained receipt stays owned by the consuming attempt.
#[derive(Debug)]
pub(super) enum GrantEvidenceFailure {
    Writer(keld_guard::WindowsGrantReceiptFailure),
    Closed(keld_guard::WindowsGenerationGrantedMember),
}
#[derive(Debug)]
struct GrantAttemptError { error:io::Error, custody:Option<GrantEvidenceFailure> }
impl From<io::Error> for GrantAttemptError {
    fn from(error:io::Error)->Self { Self { error,custody:None } }
}
fn publish(
    claim: &mut keld_guard::WindowsGenerationGrantClaim,
    parent: &cap_std::fs::Dir, leaf:&str, original:&std::fs::File,
    name:&str, access:WindowsProfilePathAccess,
) -> Result<AppliedMemberGrant,GrantAttemptError> {
    let expected_mask=match access {
        WindowsProfilePathAccess::Traverse=>0x20,
        WindowsProfilePathAccess::ReadExecute=>0x12_00a9,
        WindowsProfilePathAccess::RolePrivate=>return Err(io::Error::other("mutable data is not a code member").into()),
    };
    let role=role_for_member(name)?;
    let handle=crate::windows_fs::open_generation_grant_handle(parent,leaf,original)?;
    // Transfer the helper, never retain another WRITE_DAC clone in Update.
    let grant=claim.publish(role,handle).map_err(|failure| GrantAttemptError { error:io::Error::other(failure.error().to_string()),
        custody:Some(GrantEvidenceFailure::Writer(failure)) })?;
    if grant.receipt().permissions()!=expected_mask || grant.receipt().inheritance()!=0 {
        return Err(GrantAttemptError { error:io::Error::other("read-only grant mask or inheritance differs"),
            custody:Some(GrantEvidenceFailure::Closed(grant)) });
    }
    Ok(AppliedMemberGrant { member:name.to_owned(),grant })
}

