fn role_for_member(name:&str)->io::Result<keld_guard::WindowsGenerationResourceRole> {
    use keld_guard::WindowsGenerationResourceRole as R;
    Ok(match name {
        "<workspace>"=>R::Workspace,""=>R::PayloadRoot,"tree"=>R::TreeRoot,
        "bun.exe"=>R::Runtime,"code/main.js"=>R::Main,"code/kipc-transport.js"=>R::Transport,
        other=>R::Directory(other.strip_prefix("tree/").ok_or_else(||io::Error::other("unrecognized closed resource member"))?.to_owned()),
    })
}
fn planned_roles(stage:&UnsealedGenerationStage)->io::Result<Vec<keld_guard::WindowsGenerationResourceRole>> {
    use keld_guard::WindowsGenerationResourceRole as R;
    stage.check_inventory()?;
    let mut roles=vec![R::Workspace,R::PayloadRoot,R::TreeRoot,R::Runtime,R::Main,R::Transport,R::RoleData];
    roles.extend(stage.archive.entries().iter().filter(|entry|entry.kind()==crate::ArchiveEntryKind::Directory)
        .map(|entry|R::Directory(entry.name().to_owned())));
    Ok(roles)
}

/// Update retains complete selected-source/installation custody around Guard's
/// actual resource subset. Neither owner alone is a complete role spawn permit.
#[derive(Debug)]
pub(crate) struct PreparedSelectedWindowsGeneration {
    stage:super::seal_directories::ReadPinnedGenerationStage,
    data:super::role_data::RoleDataDirectory,
    installation:super::installation_binding::SelectedInstallationBinding,
    resources:keld_guard::WindowsPreparedGenerationResources,
}
#[derive(Debug)]
pub(super) enum GenerationResourcePreparationFailure {
    Before { detail:String, stage:ReadPinnedGrantedGeneration },
    After { stage:super::seal_directories::ReadPinnedGenerationStage,
        data:super::role_data::RoleDataDirectory,
        installation:super::installation_binding::SelectedInstallationBinding,
        failure:keld_guard::WindowsGenerationPreparationFailure },
}
impl ReadPinnedGrantedGeneration {
    /// One consuming source-bound transition; labels are resolved to actual retained
    /// pins before Guard consumes the opaque observations. Complete source and V3/v2
    /// constraints remain with Update, not converted to a caller hash or Guard proof.
    pub(super) fn prepare_resources(self)->Result<PreparedSelectedWindowsGeneration,GenerationResourcePreparationFailure> {
        match self.verify_resource_bindings() {
            Ok(())=>(),
            Err(error)=>return Err(GenerationResourcePreparationFailure::Before {detail:error.to_string(),stage:self}),
        };
        let Self { stage,registration:_,catalog:_,observations,mut data,installation,claim }=self;
        let mut grants:Vec<_>=observations.into_iter().map(|observed|observed.grant).collect();
        // Preflight proved this present; no fallible operation intervenes or aliases
        // this exclusively owned RoleDataDirectory.
        let grant=data.take_grant().expect("verified retained role-data grant");
        grants.push(grant);
        match claim.prepare_resources(grants) {
            Ok(resources)=>Ok(PreparedSelectedWindowsGeneration { stage,data,installation,resources }),
            Err(failure)=>Err(GenerationResourcePreparationFailure::After { stage,data,installation,failure }),
        }
    }
    fn verify_resource_bindings(&self)->io::Result<()> {
        let stage=self.stage.retained_stage();stage.check_inventory()?;
        for observed in &self.observations {
            let role=role_for_member(&observed.member)?;
            let pin=retained_member_pin(stage,&observed.member)?;
            if observed.grant.role()!=&role { return Err(io::Error::other("sealed grant role differs from selected inventory member")); }
            observed.grant.receipt().require_same_object(&pin).map_err(io::Error::other)?;
        }
        let (receipt,pin)=self.data.receipt_and_pin()?;
        receipt.require_same_object(&pin).map_err(io::Error::other)?;
        Ok(())
    }
}
impl PreparedSelectedWindowsGeneration {
    /// Actual resource identity only. Existing installation's exact-profile or
    /// qualified-template obligation stays retained until the final real issuer.
    pub(crate) fn resource_digest(&self)->keld_guard::WindowsGenerationResourceDigest { self.resources.resource_digest() }
    /// Revalidates retained inventory and resource readback; no live token/IPC claim.
    pub(crate) fn revalidate_resources(&self)->io::Result<()> {
        self.stage.retained_stage().check_inventory()?;
        self.resources.revalidate().map_err(io::Error::other)
    }
}
fn retained_member_pin(stage:&UnsealedGenerationStage,name:&str)->io::Result<std::fs::File> {
    if name=="<workspace>" {
        return match &stage.source_custody {
            super::GenerationSourceCustody::Workspace(workspace)=>workspace.stage_parent().try_clone().map(cap_std::fs::Dir::into_std_file),
            #[cfg(test)] super::GenerationSourceCustody::SyntheticFixture=>Err(io::Error::other("actual selected workspace required")),
        };
    }
    let directories:Vec<_>=std::iter::once(String::new()).chain(std::iter::once("tree".to_owned()))
        .chain(stage.archive.entries().iter().filter(|entry|entry.kind()==crate::ArchiveEntryKind::Directory)
            .map(|entry|format!("tree/{}",entry.name()))).collect();
    if let Some(index)=directories.iter().position(|candidate|candidate==name) {
        return stage.directories.get(index).ok_or_else(||io::Error::other("retained directory absent"))?
            .try_clone().map(cap_std::fs::Dir::into_std_file);
    }
    let index=stage.archive.entries().iter().filter(|entry|entry.kind()==crate::ArchiveEntryKind::File)
        .position(|entry|entry.name()==name).ok_or_else(||io::Error::other("member absent from complete selected inventory"))?;
    stage.files.get(index).ok_or_else(||io::Error::other("retained file absent"))?.try_clone().map(cap_std::fs::File::into_std)
}

#[cfg(test)]
mod local_custody_type_tests {
    // Trait inference is deliberately ambiguous if the concrete type becomes Send.
    // This is a compile-time control; no native registration or ACL call occurs.
    macro_rules! assert_not_send {
        ($ty:ty) => {{
            trait AmbiguousIfSend<A> { fn marker() {} }
            impl<T: ?Sized> AmbiguousIfSend<()> for T {}
            impl<T: ?Sized + Send> AmbiguousIfSend<u8> for T {}
            let _ = <$ty as AmbiguousIfSend<_>>::marker;
        }};
    }
    #[test]
    fn registration_and_every_granted_stage_remain_local() {
        assert_not_send!(keld_guard::WindowsProfileRegistration);
        assert_not_send!(super::GrantedGenerationStage);
        assert_not_send!(super::GenerationGrantFailure);
        assert_not_send!(super::ReadPinnedGrantedGeneration);
        assert_not_send!(super::GenerationSealFailure);
    }
}

//! Selected installation constraints retained across one consuming grant attempt.
//!
//! This is an obligation, not an admitted profile or a spawn permit. In particular,
//! a qualified template digest must never replace the v2 exact ProfileDigest.
use std::io;
use keld_guard::ProfileDigest;
use crate::{ArtifactIdentity, windows_baseline::SelectedGenerationIdentity};

/// No public constructor, clone, or path/record-taking authority factory.
/// The containing stage retains the actual selected source and ancestry.
#[derive(Debug)]
pub(super) struct SelectedInstallationBinding {
    artifact: ArtifactIdentity,
    constraint: crate::provenance::WindowsInstallationProfileBinding,
}

impl SelectedInstallationBinding {
    /// Accepts only closed real protected selectors. Logical v3 records cannot
    /// construct SelectedGenerationIdentity; qualified constraints are checked
    /// against this actual deployment catalog again before the first ACL grant.
    pub(super) fn from_selection(
        selection: &SelectedGenerationIdentity,
        archive: &ArtifactIdentity,
        catalog: &keld_guard::windows_qualification_catalog::DeploymentQualifiedWindowsCatalog,
    ) -> io::Result<Self> {
        require_selected_artifact(selection.artifact(), archive)?;
        Ok(Self {
            artifact: selection.artifact().clone(),
            constraint: selection.require_catalog(catalog).map_err(io::Error::other)?,
        })
    }

    /// Checks the existing exact-profile obligation without consuming custody.
    /// Caller must independently derive `applied` from actual retained generation
    /// resources. Success is only an equality check, never live OS evidence.
    pub(super) fn require_applied_profile(
        &self, archive: &ArtifactIdentity, applied: ProfileDigest,
    ) -> io::Result<()> {
        require_selected_artifact(&self.artifact, archive)?;
        let crate::provenance::WindowsInstallationProfileBinding::ExactProfileV1(expected) = &self.constraint else {
            return Err(io::Error::other("qualified template requires actual generation issuer, not exact-profile coercion"));
        };
        if *expected != applied {
            return Err(io::Error::other("selected installation requires another exact applied profile"));
        }
        Ok(())
    }
}

fn require_selected_artifact(selected: &ArtifactIdentity, actual: &ArtifactIdentity) -> io::Result<()> {
    if selected != actual {
        return Err(io::Error::other("selected complete archive identity changed"));
    }
    Ok(())
}

