//! Access subset derived from the private deployment recipe and this exact stage.
//! Complete archive authentication remains Update-owned. No caller digest/list.
use std::collections::BTreeSet;
use std::io;
use std::os::windows::fs::FileExt as _;
use keld_guard::windows_qualification_catalog::DeploymentQualifiedWindowsCatalog;
use sha2::{Digest as _, Sha256};
use super::{GenerationSourceCustody, UnsealedGenerationStage};

#[derive(Debug)]
pub(super) struct ReadPlan {
    pub(super) readable: BTreeSet<String>,
    pub(super) installation: super::installation_binding::SelectedInstallationBinding,
}

pub(super) fn derive(
    stage: &UnsealedGenerationStage,
    catalog: &DeploymentQualifiedWindowsCatalog,
) -> io::Result<ReadPlan> {
    stage.check_inventory()?;
    let workspace = match &stage.source_custody {
        GenerationSourceCustody::Workspace(workspace) => workspace,
        #[cfg(test)]
        GenerationSourceCustody::SyntheticFixture => return Err(io::Error::other("read plan requires actual selected workspace")),
    };
    let selection = workspace.source_selection();
    let host = catalog.host().identity();
    if selection.publisher_scope() != host.publisher_scope()
        || selection.artifact().app_id != host.app_id()
        || selection.artifact().target != "windows-x64"
        || stage.archive.identity() != selection.artifact()
    {
        return Err(io::Error::other("deployment host and selected stage identities differ"));
    }
    let recipe = catalog.primary_read_recipe();
    if recipe.version() != "keld.windows.primary-read-execute/v1" {
        return Err(io::Error::other("unsupported closed primary read recipe"));
    }
    let files: Vec<_> = stage.archive.entries().iter()
        .filter(|entry| entry.kind() == crate::ArchiveEntryKind::File).collect();
    let readable = require_members(files.iter().map(|entry| entry.name()), recipe.read_execute_members())?;
    let runtime_index = files.iter().position(|entry| entry.name() == recipe.runtime_member())
        .ok_or_else(|| io::Error::other("qualified runtime member absent"))?;
    if !readable.contains(recipe.runtime_member()) {
        return Err(io::Error::other("runtime absent from approved readable subset"));
    }
    let runtime = stage.files.get(runtime_index).ok_or_else(|| io::Error::other("runtime pin absent"))?;
    require_runtime_digest(runtime, files[runtime_index].size(), recipe.runtime_artifact_digest().0)?;
    let installation = super::installation_binding::SelectedInstallationBinding::from_selection(
        selection, stage.archive.identity(), catalog,
    )?;
    Ok(ReadPlan { readable, installation })
}

fn require_members<'a>(
    available: impl Iterator<Item = &'a str>, required: &[&str],
) -> io::Result<BTreeSet<String>> {
    let available: BTreeSet<_> = available.collect();
    let mut selected = BTreeSet::new();
    for name in required {
        if !selected.insert((*name).to_owned()) || !available.contains(name) {
            return Err(io::Error::other("deployment recipe member missing or duplicate"));
        }
    }
    Ok(selected)
}

fn require_runtime_digest(file: &cap_std::fs::File, size: u64, expected: [u8; 32]) -> io::Result<()> {
    if retained_runtime_sha256(file, size)? != expected {
        return Err(io::Error::other("retained runtime SHA256 differs from deployment qualification"));
    }
    Ok(())
}

fn retained_runtime_sha256(file: &cap_std::fs::File, expected_size: u64) -> io::Result<[u8; 32]> {
    let metadata = file.metadata()?;
    crate::windows_extraction::ensure_regular(&metadata)?;
    if metadata.len() != expected_size {
        return Err(io::Error::other("runtime size differs from authenticated inventory"));
    }
    let file = file.try_clone()?.into_std();
    let mut digest = Sha256::new();
    let mut offset = 0_u64;
    let mut buffer = [0_u8; 16 * 1024];
    while offset < expected_size {
        let wanted = usize::try_from((expected_size - offset).min(buffer.len() as u64))
            .map_err(io::Error::other)?;
        let count = file.seek_read(&mut buffer[..wanted], offset)?;
        if count == 0 { return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "runtime shortened")); }
        digest.update(&buffer[..count]);
        offset += u64::try_from(count).map_err(io::Error::other)?;
    }
    if file.metadata()?.len() != expected_size {
        return Err(io::Error::other("runtime changed while hashing"));
    }
    Ok(digest.finalize().into())
}

