//! Opaque selected-source resource pipeline. Not installed process admission.
#![forbid(unsafe_code)]
use std::rc::Rc;
use std::sync::Arc;
use keld_guard::WindowsProfileRegistration;
use keld_guard::windows_qualification_catalog::DeploymentQualifiedWindowsCatalog;

/// Only the protected selector can supply the complete selected source capability.
/// No raw file, archive, digest, path or synthetic constructor is public.
#[derive(Debug)]
pub struct SelectedWindowsGenerationSource {
    source: crate::windows_baseline::SelectedGenerationSource,
}
impl SelectedWindowsGenerationSource {
    pub(crate) fn from_selected(source: crate::windows_baseline::SelectedGenerationSource) -> Self {
        Self { source }
    }

    /// Materializes fresh resources and applies the closed catalog read plan using
    /// exactly one pristine registration. Retain either returned owner until the
    /// separately qualified retirement sequence completes. No process is created.
    /// # Errors
    /// Any failed step preserves its source, partial objects and profile custody.
    /// A failure is terminal: this API provides no retry or automatic cleanup.
    pub fn prepare_resources(
        self,
        registration: Rc<WindowsProfileRegistration>,
        catalog: Arc<DeploymentQualifiedWindowsCatalog>,
    ) -> Result<PreparedWindowsGenerationResources, WindowsGenerationResourceFailure> {
        let inputs = match self.source.prepare_workspace() {
            Ok(inputs) => inputs,
            Err(failure) => return Err(WindowsGenerationResourceFailure {
                custody: FailureCustody::Workspace { failure, registration, catalog },
            }),
        };
        let stage = match super::UnsealedGenerationStage::materialize(inputs) {
            Ok(stage) => stage,
            Err(failure) => return Err(WindowsGenerationResourceFailure {
                custody: FailureCustody::Materialize { failure, registration, catalog },
            }),
        };
        let granted = stage.grant_for_catalog(registration, catalog)
            .map_err(|failure| WindowsGenerationResourceFailure { custody: FailureCustody::Grant(failure) })?;
        let pinned = granted.pin_read_directories()
            .map_err(|failure| WindowsGenerationResourceFailure { custody: FailureCustody::Seal(failure) })?;
        let prepared = pinned.prepare_resources()
            .map_err(|failure| WindowsGenerationResourceFailure { custody: FailureCustody::Compose(failure) })?;
        Ok(PreparedWindowsGenerationResources { prepared })
    }
}

/// Complete selected source and actual resource custody, never a spawn permit.
/// Non-Clone; there is no conversion into raw facts, mutable state or ProfileDigest.
#[derive(Debug)]
pub struct PreparedWindowsGenerationResources {
    prepared: super::grant_join::PreparedSelectedWindowsGeneration,
}
impl PreparedWindowsGenerationResources {
    /// Typed resource-subset identity only, not the full applied profile identity.
    #[must_use]
    pub fn resource_digest(&self) -> keld_guard::WindowsGenerationResourceDigest {
        self.prepared.resource_digest()
    }
    /// Rechecks existing retained inventory and native resource observations.
    /// # Errors
    /// Refuses any inventory/readback drift. Success is not process admission.
    pub fn revalidate_resources(&self) -> std::io::Result<()> {
        self.prepared.revalidate_resources()
    }
}

/// Terminal opaque failure custody. Dropping is not a verified retirement result.
#[derive(Debug)]
pub struct WindowsGenerationResourceFailure { custody: FailureCustody }
#[derive(Debug)]
enum FailureCustody {
    Workspace {
        failure: crate::windows_baseline::GenerationWorkspaceFailure,
        registration: Rc<WindowsProfileRegistration>,
        catalog: Arc<DeploymentQualifiedWindowsCatalog>,
    },
    Materialize {
        failure: super::GenerationPreparationFailure,
        registration: Rc<WindowsProfileRegistration>,
        catalog: Arc<DeploymentQualifiedWindowsCatalog>,
    },
    Grant(super::grant_join::GenerationGrantFailure),
    Seal(super::grant_join::GenerationSealFailure),
    Compose(super::grant_join::GenerationResourcePreparationFailure),
}
impl WindowsGenerationResourceFailure {
    /// Stage label only; the full underlying failure and all objects remain owned.
    #[must_use]
    pub fn phase(&self) -> &'static str {
        match &self.custody {
            FailureCustody::Workspace { .. } => "selected workspace",
            FailureCustody::Materialize { .. } => "authenticated materialization",
            FailureCustody::Grant(_) => "closed catalog grants",
            FailureCustody::Seal(_) => "directory read pins",
            FailureCustody::Compose(_) => "selected resource composition",
        }
    }
}

/// Locates only the current authenticated Host's protected initial installation.
/// No caller path, version fallback, trust key or source tuple is accepted.
/// # Errors
/// Any locator, catalog, protected-record or selected archive refusal is terminal.
/// This performs no generation workspace creation, ACL grant or process launch.
pub fn locate_windows_initial_generation(
    host: Arc<keld_guard::VerifiedCurrentWindowsImage>,
) -> Result<(SelectedWindowsGenerationSource, Arc<DeploymentQualifiedWindowsCatalog>), crate::UpdateError> {
    let (selection, catalog) = crate::windows_baseline::locate_versioned_initial_baseline(host)?;
    let selection = Arc::new(selection);
    let source = selection.open_generation_source()?;
    Ok((SelectedWindowsGenerationSource::from_selected(source), Arc::new(catalog)))
}

//! Separate mutable role-data sibling. Never a member of executable inventory.
use std::io;
use cap_std::fs::Dir;
use keld_guard::{WindowsGenerationGrantClaim, WindowsGenerationResourceRole};
use super::UnsealedGenerationStage;

#[derive(Debug)]
pub(super) struct RoleDataDirectory {
    directory: Dir,
    name: String,
    grant: Option<keld_guard::WindowsGenerationGrantedMember>,
    grant_failure: Option<keld_guard::WindowsGrantReceiptFailure>,
}

impl UnsealedGenerationStage {
    /// Internal mechanism only: the admitted generation caller must authorize
    /// the parent and resource layout. No installed/source object is modified.
    pub(super) fn prepare_role_data(
        &self, claim: &mut WindowsGenerationGrantClaim,
    ) -> Result<RoleDataDirectory, RoleDataFailure> {
        let name = format!("{}-role-data", self.name);
        let mut state = RoleDataDirectory {
            directory: self.parent.try_clone().map_err(|error| RoleDataFailure {
                error, created: None,
            })?,
            name, grant:None, grant_failure:None,
        };
        let parent = match self.parent.try_clone() {
            Ok(parent) => parent.into_std_file(),
            Err(error) => return Err(RoleDataFailure { error, created: None }),
        };
        let directory = match crate::windows_fs::create_directory_relative(&parent, &state.name) {
            Ok(directory) => directory,
            Err(error) => return Err(RoleDataFailure { error, created: None }),
        };
        // Retain the creation immediately, before any fallible clone/readback.
        state.directory = Dir::from_std_file(directory);
        match state.grant(&self.parent, claim) {
            Ok(()) => Ok(state),
            Err(error) => Err(RoleDataFailure { error, created: Some(state) }),
        }
    }
}

#[derive(Debug)]
pub(super) struct RoleDataFailure {
    error: io::Error,
    created: Option<RoleDataDirectory>,
}

impl RoleDataDirectory {
    fn grant(&mut self, parent: &Dir, claim: &mut WindowsGenerationGrantClaim) -> io::Result<()> {
        let original = self.directory.try_clone()?.into_std_file();
        let handle = crate::windows_fs::open_generation_grant_handle(parent, &self.name, &original)?;
        // Guard consumes/closes this helper; state retains any post-write failure.
        match claim.publish(WindowsGenerationResourceRole::RoleData,handle) {
            Ok(grant)=>self.grant=Some(grant),
            Err(failure)=>{
                let detail=failure.error().to_string(); self.grant_failure=Some(failure);
                return Err(io::Error::other(detail));
            }
        }
        let receipt=self.grant.as_ref().ok_or_else(||io::Error::other("role-data grant absent"))?.receipt();
        if receipt.permissions()!=0x12_01bf || receipt.inheritance()!=3 {
            return Err(io::Error::other("mutable role data actual mask/inheritance differs"));
        }
        Ok(())
    }
}

impl RoleDataDirectory {
    pub(super) fn receipt_and_pin(&self)->io::Result<(&keld_guard::WindowsClosedGrantReceipt,std::fs::File)> {
        let grant=self.grant.as_ref().ok_or_else(||io::Error::other("actual role-data grant absent"))?;
        if grant.role()!=&WindowsGenerationResourceRole::RoleData { return Err(io::Error::other("role data tag differs")); }
        let receipt=grant.receipt();
        if self.grant_failure.is_some() { return Err(io::Error::other("failed data grant cannot prepare resources")); }
        Ok((receipt,self.directory.try_clone()?.into_std_file()))
    }
    pub(super) fn take_grant(&mut self)->Option<keld_guard::WindowsGenerationGrantedMember> { self.grant.take() }
}

//! Close creation-right directory handles and reacquire read-sharing pins.
//! Not an ACL-immutability claim, a Guard permit, or an installed profile fact.
use std::io;
use cap_fs_ext::{FollowSymlinks, MetadataExt as _, OpenOptionsFollowExt as _};
use cap_std::fs::{Dir, OpenOptions, OpenOptionsExt as _};
use windows_sys::Win32::Storage::FileSystem::{
    FILE_FLAG_BACKUP_SEMANTICS, FILE_FLAG_OPEN_REPARSE_POINT, FILE_SHARE_READ,
};
use super::{GenerationStageFailure, UnsealedGenerationStage};

#[derive(Debug)]
pub(super) struct ReadPinnedGenerationStage { stage: UnsealedGenerationStage }

impl UnsealedGenerationStage {
    /// No authority is derived from successful OS retention. Only after all
    /// security-writable grant handles have closed may this transition run.
    pub(super) fn seal_directories(mut self) -> Result<ReadPinnedGenerationStage, GenerationStageFailure> {
        match self.seal_directory_handles() {
            Ok(()) => Ok(ReadPinnedGenerationStage { stage: self }),
            Err(error) => Err(GenerationStageFailure { detail: error.to_string(), stage: self }),
        }
    }

    fn seal_directory_handles(&mut self) -> io::Result<()> {
        self.check_inventory()?;
        let mut names = vec![String::new(), "tree".to_owned()];
        names.extend(self.archive.entries().iter()
            .filter(|entry| entry.kind() == crate::ArchiveEntryKind::Directory)
            .map(|entry| format!("tree/{}", entry.name())));
        let old = std::mem::take(&mut self.directories);
        for (index, previous) in old.into_iter().enumerate() {
            let expected = previous.dir_metadata()?;
            let (parent, leaf) = if index == 0 {
                (&self.parent, self.name.as_str())
            } else {
                let (parent_name, leaf) = names[index].rsplit_once('/').unwrap_or(("", &names[index]));
                let parent_index = names.iter().position(|name| name == parent_name)
                    .ok_or_else(|| io::Error::other("seal parent absent"))?;
                (self.directories.get(parent_index).ok_or_else(|| io::Error::other("seal parent not pinned"))?, leaf)
            };
            // A read-sharing open cannot coexist with the old ADD_FILE handle.
            // The retained parent bounds the reopen; exact object identity below
            // refuses any substitution during this deliberately explicit gap.
            drop(previous);
            let mut options = OpenOptions::new();
            options.read(true).share_mode(FILE_SHARE_READ)
                .custom_flags(FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT)
                .follow(FollowSymlinks::No);
            let read_pin = parent.open_with(leaf, &options)?;
            let actual = read_pin.metadata()?;
            crate::windows_extraction::ensure_directory(&actual)?;
            if actual.dev() != expected.dev() || actual.ino() != expected.ino() {
                return Err(io::Error::other("directory identity changed across sealing"));
            }
            self.directories.push(Dir::from_std_file(read_pin.into_std()));
        }
        self.check_inventory()
    }
}

impl ReadPinnedGenerationStage {
    pub(super) fn retained_stage(&self)->&UnsealedGenerationStage { &self.stage }
}

