// Proposed safe addition inside existing windows_fs.rs. No new Win32 calls.
// This is a destination-only internal mechanism, not a public admission API.
pub(crate) fn open_generation_grant_handle(
    parent: &cap_std::fs::Dir,
    leaf: &str,
    retained_destination: &std::fs::File,
) -> std::io::Result<std::fs::File> {
    use cap_fs_ext::{FollowSymlinks, MetadataExt as _, OsMetadataExt as _, OpenOptionsFollowExt as _};
    use cap_std::fs::OpenOptionsExt as _;
    use windows_sys::Win32::Storage::FileSystem::{FILE_FLAG_BACKUP_SEMANTICS, FILE_FLAG_OPEN_REPARSE_POINT};
    keld_guard::validate_fs_component(leaf).map_err(std::io::Error::other)?;
    let expected = cap_std::fs::File::from_std(retained_destination.try_clone()?).metadata()?;
    if expected.file_attributes() & FILE_ATTRIBUTE_REPARSE_POINT != 0 {
        return Err(std::io::Error::other("generation grant target is reparse"));
    }
    let expected_volume = expected.dev();
    let expected_index = expected.ino();
    let mut options = cap_std::fs::OpenOptions::new();
    options.access_mode(READ_CONTROL | WRITE_DAC | FILE_READ_ATTRIBUTES)
        .share_mode(FILE_SHARE_READ | FILE_SHARE_WRITE)
        .custom_flags(FILE_FLAG_BACKUP_SEMANTICS | FILE_FLAG_OPEN_REPARSE_POINT)
        .follow(FollowSymlinks::No);
    let object = parent.open_with(leaf, &options)?;
    let observed = object.metadata()?;
    if observed.file_attributes() & FILE_ATTRIBUTE_REPARSE_POINT != 0
        || observed.dev() != expected_volume
        || observed.ino() != expected_index
        || observed.is_dir() != expected.is_dir()
        || expected_volume != parent.dir_metadata()?.dev()
    {
        return Err(std::io::Error::other("generation grant retained object identity differs"));
    }
    Ok(object.into_std())
}

